pub(super) const DELTA_TTTT: f64 = 2.089312511379976e-1;
pub(super) const DEGREE_TTTT: i32 = 39;

/// Semi-statically filtered f64 tier (Attene §5.1 + App. A).
pub(super) fn orient3d_tttt_filtered(l0: &LambdaF64, l1: &LambdaF64, l2: &LambdaF64, l3: &LambdaF64) -> Option<Sign> {
    if !l0.d_reliable {
        return None;
    }
    if !l1.d_reliable {
        return None;
    }
    if !l2.d_reliable {
        return None;
    }
    if !l3.d_reliable {
        return None;
    }
    let i0 = l0.l[0];
    let i1 = l0.l[1];
    let i2 = l0.l[2];
    let i3 = l0.d;
    let i4 = l1.l[0];
    let i5 = l1.l[1];
    let i6 = l1.l[2];
    let i7 = l1.d;
    let i8 = l2.l[0];
    let i9 = l2.l[1];
    let i10 = l2.l[2];
    let i11 = l2.d;
    let i12 = l3.l[0];
    let i13 = l3.l[1];
    let i14 = l3.l[2];
    let i15 = l3.d;
    let t0 = i15 * i0;
    let t1 = i3 * i12;
    let t2 = t0 - t1;
    let t3 = i15 * i1;
    let t4 = i3 * i13;
    let t5 = t3 - t4;
    let t6 = i15 * i2;
    let t7 = i3 * i14;
    let t8 = t6 - t7;
    let t9 = i15 * i4;
    let t10 = i7 * i12;
    let t11 = t9 - t10;
    let t12 = i15 * i5;
    let t13 = i7 * i13;
    let t14 = t12 - t13;
    let t15 = i15 * i6;
    let t16 = i7 * i14;
    let t17 = t15 - t16;
    let t18 = i15 * i8;
    let t19 = i11 * i12;
    let t20 = t18 - t19;
    let t21 = i15 * i9;
    let t22 = i11 * i13;
    let t23 = t21 - t22;
    let t24 = i15 * i10;
    let t25 = i11 * i14;
    let t26 = t24 - t25;
    let t27 = t14 * t26;
    let t28 = t17 * t23;
    let t29 = t27 - t28;
    let t30 = t11 * t26;
    let t31 = t17 * t20;
    let t32 = t30 - t31;
    let t33 = t11 * t23;
    let t34 = t14 * t20;
    let t35 = t33 - t34;
    let t36 = t2 * t29;
    let t37 = t5 * t32;
    let t38 = t8 * t35;
    let t39 = t36 - t37;
    let t40 = t39 + t38;
    let mut beta = 0.0f64;
    beta = beta.max(l0.beta);
    beta = beta.max(l1.beta);
    beta = beta.max(l2.beta);
    beta = beta.max(l3.beta);
    let eps = DELTA_TTTT * beta.powi(DEGREE_TTTT) + support::SUBNORMAL_GUARD;
    if !eps.is_finite() {
        return None;
    }
    let lam = t40;
    let mut s = if lam > eps {
        Sign::Positive
    } else if lam < -eps {
        Sign::Negative
    } else {
        return None;
    };
    if l0.d < 0.0 {
        s = s.flipped();
    }
    if l1.d < 0.0 {
        s = s.flipped();
    }
    if l2.d < 0.0 {
        s = s.flipped();
    }
    if l3.d < 0.0 {
        s = s.flipped();
    }
    Some(s)
}

