/// Exact rational tier (Attene §5.3). Caller guarantees every
/// implicit `d != 0` (else the predicate is Undefined).
pub(super) fn orient3d_tttt_exact(le0: &LambdaExact, le1: &LambdaExact, le2: &LambdaExact, le3: &LambdaExact) -> Sign {
    let i0 = le0.l[0].clone();
    let i1 = le0.l[1].clone();
    let i2 = le0.l[2].clone();
    let i3 = le0.d.clone();
    let i4 = le1.l[0].clone();
    let i5 = le1.l[1].clone();
    let i6 = le1.l[2].clone();
    let i7 = le1.d.clone();
    let i8 = le2.l[0].clone();
    let i9 = le2.l[1].clone();
    let i10 = le2.l[2].clone();
    let i11 = le2.d.clone();
    let i12 = le3.l[0].clone();
    let i13 = le3.l[1].clone();
    let i14 = le3.l[2].clone();
    let i15 = le3.d.clone();
    let t0 = &i15 * &i0;
    let t1 = &i3 * &i12;
    let t2 = &t0 - &t1;
    let t3 = &i15 * &i1;
    let t4 = &i3 * &i13;
    let t5 = &t3 - &t4;
    let t6 = &i15 * &i2;
    let t7 = &i3 * &i14;
    let t8 = &t6 - &t7;
    let t9 = &i15 * &i4;
    let t10 = &i7 * &i12;
    let t11 = &t9 - &t10;
    let t12 = &i15 * &i5;
    let t13 = &i7 * &i13;
    let t14 = &t12 - &t13;
    let t15 = &i15 * &i6;
    let t16 = &i7 * &i14;
    let t17 = &t15 - &t16;
    let t18 = &i15 * &i8;
    let t19 = &i11 * &i12;
    let t20 = &t18 - &t19;
    let t21 = &i15 * &i9;
    let t22 = &i11 * &i13;
    let t23 = &t21 - &t22;
    let t24 = &i15 * &i10;
    let t25 = &i11 * &i14;
    let t26 = &t24 - &t25;
    let t27 = &t14 * &t26;
    let t28 = &t17 * &t23;
    let t29 = &t27 - &t28;
    let t30 = &t11 * &t26;
    let t31 = &t17 * &t20;
    let t32 = &t30 - &t31;
    let t33 = &t11 * &t23;
    let t34 = &t14 * &t20;
    let t35 = &t33 - &t34;
    let t36 = &t2 * &t29;
    let t37 = &t5 * &t32;
    let t38 = &t8 * &t35;
    let t39 = &t36 - &t37;
    let t40 = &t39 + &t38;
    let mut s = Sign::of_rbig(&t40);
    if s == Sign::Zero {
        return Sign::Zero;
    }
    if Sign::of_rbig(&le0.d) == Sign::Negative {
        s = s.flipped();
    }
    if Sign::of_rbig(&le1.d) == Sign::Negative {
        s = s.flipped();
    }
    if Sign::of_rbig(&le2.d) == Sign::Negative {
        s = s.flipped();
    }
    if Sign::of_rbig(&le3.d) == Sign::Negative {
        s = s.flipped();
    }
    s
}

/// Inexact tiers: semi-static filter (§5.1), then intervals (§5.2).
pub(super) fn orient3d_tttt_inexact(a: &GenericPoint3D, b: &GenericPoint3D, c: &GenericPoint3D, d: &GenericPoint3D) -> Option<Sign> {
    if let Some(s) = orient3d_tttt_filtered(a.lambda_f64(), b.lambda_f64(), c.lambda_f64(), d.lambda_f64()) {
        return Some(s);
    }
    orient3d_tttt_interval(a.lambda_iv(), b.lambda_iv(), c.lambda_iv(), d.lambda_iv())
}

/// Full tier dispatcher: inexact tiers, then exact rationals.
pub(super) fn orient3d_tttt(a: &GenericPoint3D, b: &GenericPoint3D, c: &GenericPoint3D, d: &GenericPoint3D) -> Sign {
    if let Some(s) = orient3d_tttt_inexact(a, b, c, d) {
        return s;
    }
    let le0 = a.lambda_exact();
    if le0.is_undefined() {
        return Sign::Undefined;
    }
    let le1 = b.lambda_exact();
    if le1.is_undefined() {
        return Sign::Undefined;
    }
    let le2 = c.lambda_exact();
    if le2.is_undefined() {
        return Sign::Undefined;
    }
    let le3 = d.lambda_exact();
    if le3.is_undefined() {
        return Sign::Undefined;
    }
    orient3d_tttt_exact(&le0, &le1, &le2, &le3)
}

